import { readFileSync, readdirSync, writeFileSync } from "node:fs";
const files = readdirSync("supabase/migrations")
  .filter((f) => f.endsWith(".sql"))
  .sort();
writeFileSync(
  "supabase/setup.sql",
  "-- SVS fresh-project installer. Run once in Supabase SQL Editor.\n-- Existing projects: apply only the missing files in migrations/, not this installer.\n-- Generated by npm run db:bundle; no demo data, accounts, passwords or keys.\nbegin;\n\n" +
    files
      .map(
        (f) =>
          `-- SOURCE: ${f}\n${readFileSync(`supabase/migrations/${f}`, "utf8")}`,
      )
      .join("\n") +
    "\ncommit;\n",
);
console.log("Fresh-project SQL installer generated.");
